import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>模糊和打码都能藏东西，但它们不是同一种工具。一个把区域柔化成平滑的色彩，另一个把它换成大块的色块。</p>\n<p>涉及隐私时，这个差别很重要。看着已经遮住的方法，可能还留着一张可认的脸或一个可读的词，选错了就等于暴露了你本来想藏的东西。</p>\n<p>这篇文章会直接对比两种方法：原理、观感、人脸和文字分别哪种更安全，以及什么时候结合使用才能做好真正的遮盖。对比完想上手试试，<a href=\"/zh/mohu-masaike/\">图片模糊与马赛克</a>两种方法都在一个工具里，涂抹区域、调强度都很直观。</p>\n<h2 id=\"how-each-method-works\">两种方法的原理</h2>\n<p>模糊是把相邻像素的颜色平均化。锐利的边缘融化了，文字读不出来了，强度越高，人脸的特征消失得越多。</p>\n<p>打码是把区域换成纯色方块。每个方块是底下像素的平均颜色，所有精细细节都消失了，只剩粗糙的马赛克。</p>\n<p>模糊保留了原始形状的感觉。模糊的脸还能看出头在哪里，模糊的页面还能看出文字行走到哪。</p>\n<p>打码则破坏了形状。打码的脸变成一组方块，打码的一行文字变成一排色块，字母没有任何提示。</p>\n<h2 id=\"how-they-look\">并排对比观感</h2>\n<p>模糊的区域看着柔和、自然。它和照片融为一体，所以模糊在背景和人像的温和匿名处理里很受欢迎。</p>\n<p>打码的区域看着就是刻意遮挡。马赛克向观众表明这里有东西被特意藏起来了，在新闻和法律场景里很有用。</p>\n<p>想要照片好看时，模糊是更好的选择。它藏住细节又不张扬，图片依然像一张照片。</p>\n<p>遮盖本身就是重点时，打码更好。马赛克明确表示信息被移除了，这能赢得观众的信任。</p>\n<h2 id=\"safety-comparison\">哪种方法更安全</h2>\n<p>强度拉满时，两种方法都安全。重度模糊和大方块马赛克都能彻底破坏信息，导出的文件里谁也恢复不了。</p>\n<p>中等强度时，打码更安全。大方块的马赛克彻底破坏字母形状，中等模糊有时还会留下文字轮廓可读。</p>\n<p>轻度时，两种方法都不安全。轻柔模糊的脸有时能被锐化回来，小马赛克也还留着面部特征的形状。</p>\n<p>规则很简单：用你能接受的最强设置。马赛克稍强一点看着是故意的，模糊稍弱一点却会让细节暴露出来。</p>\n<h2 id=\"hiding-faces\">隐藏人脸：模糊还是打码</h2>\n<p>人脸通常用打码更安全。大方块的马赛克彻底破坏眼睛、鼻子和嘴巴，什么都认不出来。</p>\n<p>重度模糊对人脸也有效，但必须真的是重度。眼睛和微笑还看得见的轻度模糊，保护不了任何人，不管看着多柔和。</p>\n<p>不管用哪种方法，都要盖住整个头。发际线、耳朵和下巴都带有身份信息，遮盖人脸需要完全覆盖，不只是在眼睛上画一条杠。</p>\n<p>按全尺寸检查结果。放大看被遮盖的脸，确认没有任何特征可见，再检查背景里的倒影有没有再次露出这张脸。</p>\n<h2 id=\"hiding-text\">隐藏文字与数字：模糊还是打码</h2>\n<p>文字用打码明显胜出。马赛克破坏字母形状，模糊只是把它们变柔和，而人脑很擅长根据上下文读出变柔和的字母。</p>\n<p>车牌、地址或密码需要完全覆盖。哪怕只读出一位数字也可能锁定一辆车，半个地址也能把位置范围大幅缩小。</p>\n<p>整行都盖住，不只是敏感的那个词。行的长度和周围的词可能暴露被藏的部分，所以遮盖要慷慨一点。</p>\n<p>大文字用大方块，小文字用中等方块。方块要大到没有任何字母形状能留下来，放大检查就能确认。</p>\n<h2 id=\"license-plates\">车牌与车辆细节</h2>\n<p>车牌是小而高对比的目标，很容易遮盖不当。车牌上的轻度模糊，在全尺寸下常常还留着字符可读。</p>\n<p>中等方块的打码是可靠的办法。方块破坏字符形状，车牌变成一排彩色方块。</p>\n<p>盖住整个车牌，包括地区代码和边缘的小字。结合车型和颜色，半块车牌也可能锁定一辆车。</p>\n<p>检查图片里有没有第二块车牌。正面拍的车，车牌可能映在车窗倒影里；背景里的车也可能露出车牌。</p>\n<h2 id=\"documents-and-screens\">文件、屏幕与文书</h2>\n<p>文件里文字到处都是：页眉、页脚、签名、印章。只模糊一行是不够的，同样的信息可能还出现在页面其他地方。</p>\n<p>每条敏感的行都要打码，不只是最显眼的那条。页眉里的名字、页脚里的地址、正文里的身份证号，都要盖住。</p>\n<p>截图也一样。仪表盘可能在好几个面板里暴露客户姓名、内部网址和密码，每个面板都要单独遮盖。</p>\n<p>必须分享的文件，考虑把敏感部分直接裁掉。裁剪是永久去掉数据，模糊和打码只是在这一个文件里把它藏起来。</p>\n<h2 id=\"backgrounds\">背景：模糊是更好的工具</h2>\n<p>背景用模糊更好。轻柔的模糊让主体脱颖而出，照片看起来依然自然，这属于创意效果，而不是审查涂抹。</p>\n<p>背景打码看着不对。马赛克会吸引注意力，照片不再像照片，开始像一份被审查过的文件。</p>\n<p>背景用轻度模糊，敏感细节用重度模糊或马赛克。两种强度服务于不同的目的，搞混了两者都会变弱。</p>\n<p>隐私方面，模糊背景能隐藏地点。街牌、门牌号或可识别的建筑可能暴露照片的拍摄地点，模糊能去掉这条线索。</p>\n<h2 id=\"reversibility-myths\">遮盖后的图片能被还原吗</h2>\n<p>常见的担心是，模糊或打码的图片能被软件还原。实际上，重度遮盖是还原不了的，因为原始细节已经没了。</p>\n<p>模糊是把像素平均化，丢掉了精细细节。细节一旦被平均掉，任何软件都不知道原来的像素是什么。</p>\n<p>打码的破坏性更强。每个方块用一种颜色替代了几十个像素，原始信息丢了好几遍。</p>\n<p>例外是非常轻的遮盖。轻柔模糊或小马赛克留下的信息还够增强工具恢复部分画面，所以敏感细节需要高强度设置。</p>\n<h2 id=\"strength-settings\">强度设置对比</h2>\n<p>模糊强度是从轻到重的平滑刻度。低端只是稍微变软，高端变成一片色彩。</p>\n<p>马赛克方块大小是从小到大的阶梯刻度。小方块还留着形状的粗略提示，大方块把区域缩减成几块扁平的色块。</p>\n<p>同样安全级别下，大方块马赛克通常比重度模糊更强。方块是直接破坏形状，模糊只是把它变柔和。</p>\n<p>两种方法都要按全尺寸测试。放大看遮盖区域，确认没有任何东西可读或可认，不管选了哪种方法和强度。</p>\n<h2 id=\"combining-both\">模糊与打码结合使用</h2>\n<p>整张图片不一定要只用一种方法。脸涂模糊，车牌涂打码，涂抹之间切换模式就行。</p>\n<p>这种组合发挥了两种方法的长处。脸在重度模糊下看着自然，文字被马赛克彻底破坏。</p>\n<p>大面积的柔和区域用人脸和背景用模糊，小而锐利的细节用文字、数字和条码用打码。</p>\n<p>同类区域内保持强度一致。脸轻轻模糊、车牌重重打码没问题，但单独一张脸只轻轻模糊是不安全的。</p>\n<h2 id=\"legal-and-ethical\">法律与伦理提示</h2>\n<p>遮住一张脸，并不总是意味着照片可以安全发布。隐私、同意和肖像权的法律因地而异，模糊的脸在每种情况下都不一定够用。</p>\n<p>孩子需要格外小心。模糊的脸比看得见的脸好，但对无法表示同意的孩子来说，最安全的选择是不分享这张照片。</p>\n<p>新闻报道里，打码是标准做法，因为它明确表示身份受到了保护。新闻照片里的模糊人脸，可能看着像艺术选择，而不是审查涂抹。</p>\n<p>拿不准时，问问照片里的人。同意比任何遮盖技术都重要，同意被展示的人不需要被藏起来。</p>\n<h2 id=\"when-neither-is-enough\">两种方法都不够的时候</h2>\n<p>有时候遮盖根本不是正确答案。背景、元数据或上下文会暴露地点的照片，可能完全不该分享。</p>\n<p>元数据是隐藏的风险。脸模糊了的照片，可能还带有暴露拍摄地点的GPS坐标，分享前检查导出设置。</p>\n<p>上下文是另一个风险。独特房子、学校招牌或公司标志前的模糊人脸，就算遮盖得再完美，也可能认出这个人。</p>\n<p>这些情况下不要分享照片。裁得紧一点、删除元数据，或者换一张没有同样线索的图片。</p>\n<h2 id=\"choosing-for-screenshots\">截图该怎么选</h2>\n<p>截图大多是文字，所以打码通常是正确的方法。马赛克破坏字母形状，轻柔的模糊可能还留下一部分文字可读。</p>\n<p>截图用中等方块。文字很小，就算是适度的马赛克也能彻底破坏，方块再大就会盖住太多屏幕内容。</p>\n<p>涂掉姓名、邮箱地址、密码和内部网址。仪表盘截图常常比你想分享的部分暴露得更多。</p>\n<p>截图导出选PNG。无损格式让没有遮盖的文字保持锐利，截图要展示设置或报错信息时，这一点很重要。</p>\n<h2 id=\"cheat-sheet\">快速决策速查表</h2>\n<p>文字、数字、地址、车牌和密码用打码。马赛克彻底破坏形状，是任何书面内容最安全的选择。</p>\n<p>想让照片看着自然时，人脸用重度模糊。模糊去掉面部特征，图片依然像一张照片。</p>\n<p>背景用轻度模糊。它让主体脱颖而出，又不让观众注意到遮盖本身。</p>\n<p>一张图片里有不同种类的敏感细节时，两种方法一起用。脸模糊，文字打码，分享前按全尺寸检查整张图片。</p>\n<h2 id=\"blur-vs-pixelate-social\">社交媒体上的模糊与打码</h2>\n<p>社交平台上传时会压缩图片，压缩对模糊和打码的影响不同。轻度模糊压缩后可能变弱，马赛克则保持强劲。</p>\n<p>社交媒体上必须隐藏的人脸，打码是更安全的选择。马赛克经得起压缩和重新编码，轻柔的模糊可能变薄到露出面部特征。</p>\n<p>想要柔和的背景时，模糊是更好的选择。轻度模糊在信息流里看着自然，打码的背景看着像个错误。</p>\n<p>平台压缩后也要测试遮盖图片。发一条测试帖子，把图片下载回来，检查敏感细节在压缩后的画质下是否还藏着。</p>\n<p>分步骤的操作见<a href=\"/zh/blog/ruhe-mohu-dama-tupian/\">如何模糊或打码图片</a>。完整概览见<a href=\"/zh/blog/tupian-mohu-masaike-wanquan-zhinan/\">图片模糊与马赛克完全指南</a>；想彻底删除位置数据，用<a href=\"/zh/shanchu-tupian-yuanshuju/\">删除图片元数据工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"隐藏人脸时，模糊和打码哪个更好？","answer":"打码通常更安全，因为大方块马赛克能彻底破坏面部特征。重度模糊也有效，但必须真的是重度。眼睛和微笑还看得见的轻度模糊保护不了任何人，不管用哪种方法都一样。"},{"question":"有人能用AI软件把照片还原清晰吗？","answer":"模糊够重或马赛克够大时，不能。两种方法都破坏了原始像素细节，软件没有什么可恢复的。很轻的模糊有时能被锐化回来，所以敏感细节需要高强度设置。"},{"question":"截图里的密码应该模糊还是打码？","answer":"打码。中等方块的马赛克能彻底破坏字符，轻柔的模糊可能还留下轮廓可读。整个密码输入框都盖住，不只是字符本身，因为输入框的长度也可能泄露线索。"},{"question":"眼睛上画一条黑杠就够藏住人脸吗？","answer":"不够。脸的其余部分，包括鼻子、嘴巴、发际线和下巴，依然可认。用重度模糊或大方块马赛克盖住整个头部，分享前按全尺寸检查结果。"},{"question":"一张图片里能同时用模糊和打码吗？","answer":"能。人脸涂重度模糊，文字或车牌涂打码，涂抹之间切换模式就行。这样发挥了两种方法的长处：人脸看着自然，文字被彻底破坏。"},{"question":"遮盖照片也会清除位置信息吗？","answer":"遮盖本身不会。遮盖藏住了看得见的细节，但文件里可能还带有GPS坐标。用工具导出时会清除GPS标签，删除图片元数据工具能删掉其余部分。分享前检查下载好的文件。"}];
